import{_ as t,o,c as s,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Time zone","description":"","frontmatter":{},"headers":[],"relativePath":"guide/time-zone.md","filePath":"guide/time-zone.md"}'),n={name:"guide/time-zone.md"};function i(r,e,l,h,c,d){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="time-zone" tabindex="-1">Time zone <a class="header-anchor" href="#time-zone" aria-label="Permalink to &quot;Time zone&quot;">​</a></h1><p>Orbit stores every time in UTC and shows it in a time zone of your choice: one for the installation, and one per person who wants something else.</p><h2 id="installation" tabindex="-1">Orbit&#39;s clock <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Orbit&#39;s clock {#installation}&quot;">​</a></h2><p>The installation&#39;s time zone is asked for on the first run, with the browser&#39;s zone suggested, and lives in <strong>Settings → General → Time zone</strong> under <strong>Orbit&#39;s clock</strong>. Only an administrator changes it. Until someone does, Orbit uses UTC.</p><p>It is the zone Orbit writes times in when nobody is looking at the console:</p><ul><li>notifications on Slack, Discord and email, which now name the zone, as in <code>14:00 (America/Sao_Paulo)</code>;</li><li>invitation emails;</li><li>the public status page;</li><li>the default for new schedules, described below.</li></ul><p>Changing it never moves a schedule that already exists.</p><h2 id="yours" tabindex="-1">Your clock <a class="header-anchor" href="#yours" aria-label="Permalink to &quot;Your clock {#yours}&quot;">​</a></h2><p>Everyone can pick their own zone in the same card, under <strong>Your clock</strong>. It changes only what that person sees: every date and time in the console, including the activity feed&#39;s days. The choice is kept with the account, so it follows you to any browser. Leave it on <strong>Follow Orbit</strong> to see the installation&#39;s zone.</p><h2 id="schedules" tabindex="-1">Schedules <a class="header-anchor" href="#schedules" aria-label="Permalink to &quot;Schedules {#schedules}&quot;">​</a></h2><p>Each schedule keeps its own zone, so it reads the same whoever looks at it:</p><ul><li><strong>Backups and restore tests:</strong> the policy&#39;s time zone, offered as the installation&#39;s zone for a new policy. Schedules saved before Orbit had a time zone stay in UTC.</li><li><strong>Jobs:</strong> the job&#39;s time zone, chosen with the cron expression when the job is created or in its settings. A new job takes the installation&#39;s zone; jobs created before this setting existed run in UTC and say so.</li></ul><p>Schedules follow daylight saving: a time the clock skips runs when the clock jumps forward.</p><h2 id="utc" tabindex="-1">What stays in UTC <a class="header-anchor" href="#utc" aria-label="Permalink to &quot;What stays in UTC {#utc}&quot;">​</a></h2><p>The API, the database, logs on the server and the CLI keep UTC, so an export or a log line reads the same on every machine. The time zone only changes how Orbit writes times for people.</p>',15)])])}const p=t(n,[["render",i]]);export{m as __pageData,p as default};
